<script>
	let text = $state('');

	const wordCount = $derived.by(() => {
		if (!text.trim()) return 0;
		return text.trim().split(/\s+/).filter(Boolean).length;
	});

	const charCount = $derived.by(() => {
		if (!text.trim()) return 0;
		return text.trim().length;
	});

	const isLong = $derived.by(() => wordCount > 15);
</script>

<div class="container">
	<div class="input-group">
		<input
			data-testid="text-input"
			type="text"
			value={text}
			oninput={(e) => text = e.target.value}
			placeholder="Enter some text..."
		/>
		<button
			data-testid="clear-button"
			onclick={() => text = ''}
		>
			Clear
		</button>
	</div>

	<div class="stats">
		<p data-testid="word-count">Words: {wordCount}</p>
		<p data-testid="char-count">Characters: {charCount}</p>
		<p data-testid="length-indicator">
			{isLong ? 'Status: Long text' : 'Status: Short text'}
		</p>
	</div>
</div>

<style>
