<script>
	import { inspect } from 'svelte/inspect';

	let text = $state('Hello world');

	// Basic inspect logging
	$inspect(text);

	// inspect with custom callback
	$inspect(text).with(value => {
		console.log('Text updated to:', value);
	});

	// inspect trace inside effect
	$effect(() => {
		$inspect.trace(text, {
			label: 'Input',
			formatter: ({ value }) => `Text: ${value}`
		});
	});
</script>

<div class="container">
	<input
		data-testid="text-input"
		type="text"
		bind:value={text}
		placeholder="Enter text to see $inspect in action"
	/>
	<p data-testid="text-value">Current text: "{text}"</p>
	<p data-testid="char-count">Character count: {text.length}</p>
</div>

<style>
