<script>
  let { name = 'World', count = 0, showDetails = false } = $props();

  let countState = $state(count);

  function increment() {
    countState++;
  }
</script>

<div>
  <h1 data-testid="name-display">Hello, {name}!</h1>
  <p data-testid="count-display">Count: {countState}</p>
  <button data-testid="increment-button" onclick={increment}>Increment</button>

  {#if showDetails}
    <div data-testid="details">
      <p>Name is {name}</p>
      <p>Count is {countState}</p>
      <p>ShowDetails is {showDetails}</p>
    </div>
  {/if}
</div>
